std::string buf = FUZZ_PARAM_STR();
if (buf.size() > 1024) buf.resize(1024);
// Half-open range [a, b)
size_t a = (buf.size() == 0) ? 0 : (*FUZZ_PARAM(unsigned int) % buf.size());
size_t b = (buf.size() == 0) ? 0 : (a + (*FUZZ_PARAM(unsigned int) % (buf.size() - a + 1)));
std::string d1 = url_decode(buf.data() + a, buf.data() + b);
(void)d1;
// Pointer + length overload
size_t len = (buf.size() == 0) ? 0 : (*FUZZ_PARAM(unsigned int) % (buf.size() + 1));
std::string d2 = url_decode(buf.data(), len);
(void)d2;
// C-string overload
std::string cstr = FUZZ_PARAM_STR();
if (cstr.size() > 1024) cstr.resize(1024);
std::string d3 = url_decode(cstr.c_str());
(void)d3;
