// Validation: All ranges/lengths constrained valid; decoding behavior left unspecified by API.

// Construct an InetResolver::Addr and optionally populate with IPv4/IPv6 entries.
// The struct is user-managed; we ensure internal consistency of type and entries.
InetResolver::Addr *addr = new InetResolver::Addr();
// Decide which family to populate and how many entries using fuzz data.
unsigned int r = *FUZZ_PARAM(unsigned int);
unsigned int family_sel = r % 3; // 0: UNDEFINED(empty), 1: IN4, 2: IN6
if (family_sel == 0) {
