    addr->type = InetResolver::UNDEFINED;
    addr->addr.clear();
} else if (family_sel == 1) {
    addr->type = InetResolver::IN4;
    addr->addr.clear();
    // 1..3 IPv4 entries, each 4 bytes
    unsigned int n = (r % 3) + 1;
