import random
import string
from typing import List, Tuple

# Generator for valid HTTP header lines (single line: Name: value, no CR/LF)
# Focus: produce syntactically valid yet diverse headers to exercise parsing and behavior.
# The fuzzer stub uses FUZZ_PARAM_STR() to obtain a header string that is passed to
# WebClient::Request::add_header. We therefore emit bytes that decode to UTF-8 text for
# a single header line without CR/LF.

# Constraints
# - Single line, no CR (\r) or LF (\n)
# - Must include a colon separating name and value
# - Keep total size <= 4096 bytes
# - Try a wide variety of interesting but valid headers, including duplicates, unusual
#   casing, long values, parameters, commas, quoted-strings, and whitespace variations.

# We return bytes so the harness can feed it directly. The content is UTF-8 text.

STD_HEADERS: List[str] = [
    "Host",
    "User-Agent",
    "Accept",
    "Accept-Encoding",
    "Accept-Language",
    "Cache-Control",
    "Pragma",
    "Connection",
    "Upgrade-Insecure-Requests",
    "Range",
    "If-Modified-Since",
    "If-None-Match",
    "ETag",
    "Content-Type",
    "Content-Length",
    "Transfer-Encoding",
    "TE",
    "Trailer",
    "Origin",
    "Referer",
    "Cookie",
    "Set-Cookie",
    "Authorization",
    "Proxy-Authorization",
    "X-Requested-With",
    "X-Forwarded-For",
    "X-Forwarded-Proto",
    "Via",
    "DNT",
    "Upgrade",
    "Expect",
    "Date",
    "Expires",
    "Last-Modified",
    "Location",
    "Server",
    "Vary",
]

TOKEN_CHARS = string.ascii_letters + string.digits + "!#$%&'*+-.^_`|~"
WS = [" ", "\t"]

def _rand_token(r: random.Random, min_len: int = 1, max_len: int = 12) -> str:
    n = r.randint(min_len, max_len)
    return ''.join(r.choice(TOKEN_CHARS) for _ in range(n))

def _rand_quoted_string(r: random.Random, min_len: int = 0, max_len: int = 40) -> str:
    # Generate RFC7230-ish quoted-string with simple escapes
    n = r.randint(min_len, max_len)
    buf = []
    for _ in range(n):
        ch = r.choice(string.ascii_letters + string.digits + string.punctuation + ' ')
        # avoid CR/LF and embedded quotes; sometimes escape
        if ch in ['\r', '\n']:
            ch = ' '
        if ch == '"' and r.random() < 0.5:
            buf.append('\\"')
        elif ch == '\\' and r.random() < 0.3:
            buf.append('\\\\')
        else:
            buf.append(ch)
    return '"' + ''.join(buf) + '"'

def _rand_parameters(r: random.Random, count_range: Tuple[int, int] = (0, 4)) -> str:
    n = r.randint(*count_range)
    parts = []
    for _ in range(n):
        attr = _rand_token(r, 1, 10)
        if r.random() < 0.5:
            val = _rand_token(r, 0, 12)
        else:
            val = _rand_quoted_string(r, 0, 20)
        sep_ws = r.choice(WS) if r.random() < 0.6 else ''
        parts.append(f";{sep_ws}{attr}={val}")
    return ''.join(parts)

def _header_name(r: random.Random) -> str:
    # Sometimes choose from known list; sometimes synthesize token
    if r.random() < 0.75:
        name = r.choice(STD_HEADERS)
        # Randomize casing
        def rc(c: str) -> str:
            if c.isalpha() and r.random() < 0.5:
                return c.lower()
            if c.isalpha() and r.random() < 0.5:
                return c.upper()
            return c
        return ''.join(rc(c) for c in name)
    else:
        # Custom header like X-..., with varied tokens
        prefix = r.choice(["X-", "x-", "X-My-", "X-Trace-", "X-Custom-"])
        return prefix + _rand_token(r, 3, 12)

def _make_value_for_name(r: random.Random, name: str) -> str:
    lname = name.lower()
    # Produce plausible yet diverse values tailored by header name
    if lname == 'host':
        host = '.'.join(_rand_token(r, 1, r.randint(1, 10)).lower() for _ in range(r.randint(2, 4)))
        if r.random() < 0.5:
            port = r.choice([80, 8080, 8000, 443, r.randint(1, 65535)])
            return f"{host}:{port}"
        return host
    if lname in ('user-agent',):
        ua_core = r.choice([
            'Mozilla/5.0',
            'curl/7.' + str(r.randint(10, 90)),
            'Wget/1.' + str(r.randint(10, 99)),
            'python-requests/' + str(r.randint(1, 3)) + '.' + str(r.randint(0, 9)),
        ])
        extras = []
        if r.random() < 0.6:
            extras.append('(X11; Linux x86_64)')
        if r.random() < 0.4:
            extras.append('AppleWebKit/537.36 (KHTML, like Gecko) Chrome/{} Safari/537.36'.format(r.randint(60, 125)))
        return ' '.join([ua_core] + extras)
    if lname in ('accept',):
        # MIME types with q-params
        types = [
            'text/html', 'application/json', 'application/xml', 'image/webp',
            'text/*', '*/*', 'application/octet-stream'
        ]
        vals = []
        for _ in range(r.randint(1, 5)):
            t = r.choice(types)
            if r.random() < 0.6:
                t += _rand_parameters(r, (0, 2))
            if r.random() < 0.7:
                q = 1.0 - r.random() * 0.9
                vals.append(f"{t};q={q:.3f}")
            else:
                vals.append(t)
        return ', '.join(vals)
    if lname in ('accept-encoding',):
        encs = ['gzip', 'deflate', 'br', 'zstd', 'identity', '*']
        return ', '.join(sorted(set(r.choice(encs) for _ in range(r.randint(1, 5)))))
    if lname in ('accept-language',):
        langs = ['en-US', 'en', 'fr-FR', 'de-DE', 'es-ES', 'ja-JP', 'zh-CN']
        items = []
        for _ in range(r.randint(1, 5)):
            l = r.choice(langs)
            if r.random() < 0.6:
                q = 1.0 - r.random() * 0.9
                l = f"{l};q={q:.2f}"
            items.append(l)
        return ', '.join(items)
    if lname in ('cache-control',):
        dirs = ['no-cache', 'no-store', 'max-age=' + str(r.randint(0, 86400)), 'public', 'private', 'must-revalidate']
        return ', '.join(sorted(set(r.choice(dirs) for _ in range(r.randint(1, 4)))))
    if lname in ('pragma',):
        return r.choice(['no-cache', ''])
    if lname in ('connection',):
        return r.choice(['keep-alive', 'close', 'Upgrade'])
    if lname in ('upgrade',):
        return r.choice(['websocket', 'h2c', 'TLS/1.3'])
    if lname in ('upgrade-insecure-requests', 'dnt', 'te'):
        return r.choice(['0', '1'])
    if lname in ('range',):
        # e.g., bytes=0-499, bytes=500-999, bytes=-500, bytes=9500-
        typ = 'bytes'
        if r.random() < 0.5:
            a = r.randint(0, 10000)
            b = a + r.randint(0, 10000)
            return f"{typ}={a}-{b}"
        else:
            if r.random() < 0.5:
                return f"{typ}=-{r.randint(1, 5000)}"
            else:
                return f"{typ}={r.randint(0, 10000)}-"
    if lname in ('if-modified-since', 'date', 'expires', 'last-modified'):
        # RFC 7231 IMF-fixdate
        wkday = r.choice(['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'])
        day = r.randint(1, 28)
        mon = r.choice(['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'])
        year = r.randint(1990, 2038)
        hh = r.randint(0, 23)
        mm = r.randint(0, 59)
        ss = r.randint(0, 59)
        return f"{wkday}, {day:02d} {mon} {year} {hh:02d}:{mm:02d}:{ss:02d} GMT"
    if lname in ('if-none-match', 'etag'):
        # ETag with optional W/ and quoted string
        tag = _rand_token(r, 1, 16)
        weak = 'W/' if r.random() < 0.5 else ''
        return f"{weak}\"{tag}\""
    if lname in ('content-type',):
        base = r.choice([
            'application/json',
            'application/x-www-form-urlencoded',
            'multipart/form-data',
            'text/plain',
            'application/octet-stream'
        ])
        if base == 'multipart/form-data':
            # Always include boundary for realism
            b = _rand_token(r, 24, 40)
            return f"{base}; boundary={b}"
        if base == 'application/x-www-form-urlencoded' and r.random() < 0.7:
            # Optional charset
            cs = r.choice(['utf-8', 'iso-8859-1', 'utf-16'])
            return f"{base}; charset={cs}"
        return base + _rand_parameters(r, (0, 2))
    if lname in ('content-length',):
        return str(r.randint(0, 1_000_000))
    if lname in ('transfer-encoding',):
        codings = ['chunked', 'gzip', 'deflate', 'trailers']
        return ', '.join(sorted(set(r.choice(codings) for _ in range(r.randint(1, 3)))))
    if lname in ('trailer',):
        # Trailer header lists token names
        toks = [_rand_token(r, 1, 8) for _ in range(r.randint(1, 4))]
        return ', '.join(toks)
    if lname in ('origin', 'referer', 'location'):
        schemes = ['http', 'https']
        host = '.'.join(_rand_token(r, 1, r.randint(1, 10)).lower() for _ in range(r.randint(2, 4)))
        path = '/' + '/'.join(_rand_token(r, 0, 8) for _ in range(r.randint(0, 4)))
        q = ''
        if r.random() < 0.4:
            qparams = []
            for _ in range(r.randint(1, 3)):
                qparams.append(f"{_rand_token(r,1,6)}={_rand_token(r,0,8)}")
            q = '?' + '&'.join(qparams)
        return f"{r.choice(schemes)}://{host}{path}{q}"
    if lname in ('cookie',):
        # Cookie crumb list
        crumbs = []
        for _ in range(r.randint(1, 5)):
            crumbs.append(f"{_rand_token(r,1,8)}={_rand_token(r,0,12)}")
        return '; '.join(crumbs)
    if lname in ('set-cookie',):
        # Generate one Set-Cookie syntax; still valid as a header line
        name = _rand_token(r, 1, 8)
        val = _rand_token(r, 0, 12)
        attrs = []
        if r.random() < 0.7:
            attrs.append('Path=/' )
        if r.random() < 0.7:
            attrs.append('HttpOnly')
        if r.random() < 0.6:
            attrs.append('Secure')
        if r.random() < 0.5:
            attrs.append('SameSite=' + r.choice(['Lax','Strict','None']))
        return '; '.join([f"{name}={val}"] + attrs)
    if lname in ('authorization', 'proxy-authorization'):
        if r.random() < 0.7:
            # Basic base64-ish token; we won't compute real b64 every time to keep speed,
            # but still produce typical-looking token
            uid = _rand_token(r, 1, 8)
            pwd = _rand_token(r, 0, 8)
            # create a simple base64-like alphabet string length multiple of 4
            raw = f"{uid}:{pwd}".encode('utf-8')
            import base64
            b64 = base64.b64encode(raw).decode('ascii')
            return f"Basic {b64}"
        else:
            # Other scheme with token and parameters
            scheme = r.choice(['Bearer', 'Digest'])
            if scheme == 'Bearer':
                token = ''.join(r.choice(string.ascii_letters + string.digits + '-._~') for _ in range(r.randint(16, 48)))
                return f"Bearer {token}"
            # Simple Digest params (not fully compliant, but valid-ish)
            params = [
                f"username={_rand_quoted_string(r,2,8)}",
                f"realm={_rand_quoted_string(r,3,8)}",
                f"nonce={_rand_quoted_string(r,6,12)}",
                f"uri={_rand_quoted_string(r,1,12)}",
                f"response={_rand_quoted_string(r,8,16)}"
            ]
            return 'Digest ' + ', '.join(params)
    if lname in ('vary',):
        fields = ['Accept', 'Accept-Encoding', 'User-Agent', '*']
        return ', '.join(sorted(set(r.choice(fields) for _ in range(r.randint(1, 3)))))
    if lname in ('server',):
        return r.choice(['nginx', 'Apache', 'Caddy', 'lighttpd']) + '/' + str(r.randint(1, 3)) + '.' + str(r.randint(0, 99))
    # Default: generic token with optional parameters and quoted section
    base = _rand_token(r, 1, 16)
    if r.random() < 0.5:
        base += _rand_parameters(r, (0, 3))
    if r.random() < 0.3:
        base += ' ' + _rand_quoted_string(r, 0, 20)
    return base

def _assemble_header(r: random.Random) -> str:
    name = _header_name(r)
    # Optional whitespace around colon and after
    pre = '' if r.random() < 0.7 else r.choice(WS)
    post = r.choice(['', ' ', '\t', '  ', '\t ']) if r.random() < 0.95 else ''
    value = _make_value_for_name(r, name)
    # Ensure no CR/LF
    value = value.replace('\r', ' ').replace('\n', ' ')
    # Optionally add leading/trailing OWS around value
    if r.random() < 0.5:
        value = (r.choice(['', ' ', '\t']) + value + r.choice(['', ' ', '\t']))
    header = f"{name}{pre}:{post}{value}"
    # Ensure overall length cap
    if len(header) > 4000:
        header = header[:4000]
    return header

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a generation strategy to diversify headers significantly
    strategy = r.random()

    if strategy < 0.15:
        # Long header value (stress long but valid single line)
        name = r.choice(['Cookie', 'X-Trace-Id', 'Set-Cookie'])
        base = _make_value_for_name(r, name)
        # Expand with comma/semicolon separated segments to be long yet single-line
        sep = r.choice([', ', '; '])
        extra = sep.join(_rand_token(r, 8, 16) for _ in range(r.randint(10, 80)))
        value = (base + sep + extra)[:3800]
        header = f"{name}: {value}"
        return header.encode('utf-8')

    if strategy < 0.30:
        # Header with complex parameters and quoted strings
        name = r.choice(['Content-Type', 'Accept', 'Authorization'])
        header = f"{name}: {_make_value_for_name(r, name)}"
        return header.encode('utf-8')

    if strategy < 0.45:
        # Whitespace variants around colon and value
        name = _header_name(r)
        value = _make_value_for_name(r, name)
        header = f"{name}\t:  {value}"
        return header.encode('utf-8')

    if strategy < 0.60:
        # Duplicate-looking custom header name with hyphens and mixed case
        name = 'X-' + _rand_token(r, 3, 6) + '-' + _rand_token(r, 3, 6)
        value = _make_value_for_name(r, name)
        header = f"{name}: {value}"
        return header.encode('utf-8')

    if strategy < 0.75:
        # Authorization flavors
        name = r.choice(['Authorization', 'Proxy-Authorization'])
        header = f"{name}: {_make_value_for_name(r, name)}"
        return header.encode('utf-8')

    if strategy < 0.90:
        # Content headers commonly affecting behavior
        name = r.choice(['Content-Length', 'Transfer-Encoding', 'TE', 'Trailer'])
        header = f"{name}: {_make_value_for_name(r, name)}"
        return header.encode('utf-8')

    # Default: general header assembly path
    header = _assemble_header(r)
    return header.encode('utf-8')

import random
import string
from typing import List

# Data type: HTTP header name
# We want to generate valid, interesting header names and paired values to exercise:
# - WebClient::add_header (expects "Name: value" after stub concatenation)
# - WebClient::header_value (expects just the header name)
# FUZZ_PARAM_STR is used twice in add_header (name, value) and once in header_value (name).
# Our buffer should contain multiple NUL-terminated strings the fuzzer can slice, or a simple
# length-prefixed encoding. Most fuzz harnesses back FUZZ_PARAM_STR from a single blob by
# splitting at delimiters. We'll encode as a simple text blob with newlines separating fields,
# avoiding CR/LF inside header names/values except as separators.
# We include a corpus of common/edge-case header names and values, and assemble a block like:
#   name1\nvalue1\nname2\nvalue2\n...
# Names are RFC 7230 token: one or more of tchar = !#$%&'*+-.^_`|~ and DIGIT/ALPHA, but in practice
# we stick to letters, digits, and hyphen to maximize acceptance. Avoid CR/LF within tokens.

MAX_TOTAL = 4096

COMMON_HEADER_NAMES = [
    "Host",
    "User-Agent",
    "Accept",
    "Accept-Encoding",
    "Accept-Language",
    "Cache-Control",
    "Connection",
    "Pragma",
    "Referer",
    "Upgrade-Insecure-Requests",
    "Sec-Fetch-Mode",
    "Sec-Fetch-Site",
    "Sec-Fetch-Dest",
    "If-Modified-Since",
    "If-None-Match",
    "Range",
    "Content-Type",
    "Content-Length",
    "Transfer-Encoding",
    "Authorization",
    "Cookie",
    "Set-Cookie",
    "ETag",
    "Location",
    "X-Requested-With",
    "X-Forwarded-For",
    "X-Real-IP",
    "DNT",
    "TE",
    "Accept-Charset",
    "Date",
    "Via",
    "Warning",
    "Origin",
    "Upgrade",
]

# Add interesting custom/edge-case styled names
EDGE_HEADER_NAMES = [
    # Case-insensitivity and hyphen positions
    "x-custom",
    "X-CUSTOM",
    "x-CuStOm",
    # Long header name with many hyphens
    "X-Long-Header-Name-With-Many-Hyphens-And123",
    # Token characters allowed besides hyphen
    "X_token",
    "X.token",
    "X^Token",
    "X~Token",
    "X|Token",
    "X`Token",
]

COMMON_VALUES = [
    "text/html",
    "application/json",
    "gzip, deflate, br",
    "en-US,en;q=0.9",
    "no-cache",
    "keep-alive",
    "max-age=0",
    "bytes=0-",
    "Basic dXNlcjpwYXNz",
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
    "sessionid=abcdef; theme=dark",
    "utf-8",
    "chunked",
    "Mon, 01 Jan 2024 00:00:00 GMT",
    "https://example.com/path",
]

# Generate a valid HTTP header name: letters/digits/hyphen with varied length and case.

def gen_header_name(rnd: random.Random) -> str:
    # 60% pick from curated lists for realistic coverage, 40% random token
    p = rnd.random()
    if p < 0.4:
        return rnd.choice(COMMON_HEADER_NAMES)
    elif p < 0.6:
        return rnd.choice(EDGE_HEADER_NAMES)
    else:
        length = rnd.randint(3, 32)
        alphabet = string.ascii_letters + string.digits + "-._^`|~"  # token-ish
        # Ensure starts with letter to be conventional
        first = rnd.choice(string.ascii_letters)
        rest = ''.join(rnd.choice(alphabet) for _ in range(length - 1))
        # Normalize to avoid colon/space, and no CR/LF
        token = (first + rest).replace(":", "-").replace(" ", "-")
        token = token.replace("\r", "").replace("\n", "")
        return token

# Generate a matching value appropriate for the name

def gen_header_value(rnd: random.Random, name: str) -> str:
    lname = name.lower()
    if lname == "host":
        host = rnd.choice(["example.com", "localhost", "www.test.local", "api.service", "xn--exmple-cua.com"])  # includes puny-like
        if rnd.random() < 0.5:
            host += f":{rnd.choice([80, 443, 8080, 8000, 8443])}"
        return host
    if lname == "user-agent":
        return rnd.choice([
            "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/120.0 Safari/537.36",
            "curl/8.5.0",
            "Wget/1.21.3",
        ])
    if lname == "accept":
        return rnd.choice(["*/*", "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8"]) 
    if lname == "accept-encoding":
        return rnd.choice(["gzip", "gzip, deflate", "br, gzip, deflate"]) 
    if lname == "accept-language":
        return rnd.choice(["en-US,en;q=0.9", "en;q=0.8, fr;q=0.7"]) 
    if lname == "cache-control":
        return rnd.choice(["no-cache", "no-store", "max-age=0", "max-age=600, must-revalidate"]) 
    if lname == "connection":
        return rnd.choice(["keep-alive", "close"]) 
    if lname == "pragma":
        return rnd.choice(["no-cache"]) 
    if lname == "referer":
        return rnd.choice(["https://example.com/", "http://localhost/"]) 
    if lname == "if-modified-since":
        return rnd.choice(["Mon, 01 Jan 2024 00:00:00 GMT", "Tue, 02 Jan 2024 12:34:56 GMT"]) 
    if lname == "if-none-match":
        return rnd.choice(['"abc123"', 'W/"weak-etag"'])
    if lname == "range":
        start = rnd.randint(0, 1024)
        return f"bytes={start}-"
    if lname == "content-type":
        return rnd.choice([
            "application/json",
            "text/plain; charset=utf-8",
            "application/x-www-form-urlencoded",
            "multipart/form-data; boundary=--------------------------%d" % rnd.randint(10**10, 10**11-1),
        ])
    if lname == "content-length":
        return str(rnd.randint(0, 2048))
    if lname == "transfer-encoding":
        return rnd.choice(["chunked", "identity"]) 
    if lname == "authorization":
        return rnd.choice(["Basic dXNlcjpwYXNz", "Bearer abc.def.ghi"]) 
    if lname == "cookie":
        return rnd.choice(["sid=abcd; theme=dark", "a=1; b=2; c=3"]) 
    if lname == "x-forwarded-for":
        return rnd.choice(["203.0.113.1", "198.51.100.2, 10.0.0.1"]) 
    if lname == "x-real-ip":
        return rnd.choice(["192.0.2.5", "2001:db8::1"]) 
    if lname == "te":
        return rnd.choice(["trailers", "gzip"])
    if lname == "upgrade":
        return rnd.choice(["websocket", "h2c"])
    # Fallback generic values
    if rnd.random() < 0.5:
        return rnd.choice(COMMON_VALUES)
    # Random token/value without CR/LF
    length = rnd.randint(1, 64)
    alphabet = string.ascii_letters + string.digits + " .,/;:_+-=()[]{}@"  # spaces allowed in values
    val = ''.join(rnd.choice(alphabet) for _ in range(length))
    return val.replace("\r", " ").replace("\n", " ")

# Assemble a blob containing several name/value pairs and standalone names for header_value lookup.

def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    parts: List[str] = []

    # Ensure we include a Host header and a few core ones to build a plausible set
    core_names = ["Host", "User-Agent", "Accept", "Accept-Encoding", "Connection"]
    rnd.shuffle(core_names)

    count_pairs = rnd.randint(5, 15)
    used_names = set()

    for i in range(count_pairs):
        if i < len(core_names):
            name = core_names[i]
        else:
            # 30% reuse an existing name with different value to test overwrite/dup handling
            if used_names and rnd.random() < 0.3:
                name = rnd.choice(list(used_names))
            else:
                name = gen_header_name(rnd)
        used_names.add(name)
        value = gen_header_value(rnd, name)
        # Store as two newline-separated fields: name then value
        parts.append(name)
        parts.append(value)

    # Add a batch of standalone header names for header_value queries,
    # including some that were not added above to exercise negative lookups
    query_names = set()
    for _ in range(rnd.randint(5, 12)):
        if rnd.random() < 0.6 and used_names:
            qn = rnd.choice(list(used_names))
        else:
            qn = gen_header_name(rnd)
        query_names.add(qn)
    for q in query_names:
        parts.append(q)

    blob = "\n".join(parts)
    data = blob.encode("utf-8", errors="ignore")
    # Enforce size limit
    if len(data) > MAX_TOTAL:
        data = data[:MAX_TOTAL]
        # Avoid truncating in the middle of a UTF-8 sequence is fine due to ASCII-only content
        # Ensure last byte is not a newline to prevent empty trailing field
        if data and data[-1] == 0x0A:
            data = data[:-1]
    return data

import random
import string
from typing import List

# Generator for inputs targeting WebClient::make_multipart_form_data fuzz stub
# Encodes multiple FUZZ_PARAM_STR values into a single bytes buffer using a
# simple length-prefixed scheme so the harness can extract consistent strings.
# Layout:
#   [count (1 byte: number of parts 1..3)]
#   For each part:
#       [part_data_len (2 bytes LE)] [part_data bytes]
#       [has_cd (1 byte 0/1)]
#       if has_cd:
#           [name_len (1 byte)] [name bytes]
#           [filename_len (1 byte)] [filename bytes]
#   [boundary_len (1 byte)] [boundary bytes]
# Total size limited to <= 4096 bytes.

SAFE_ASCII = string.ascii_letters + string.digits + "-_.,:/@+% "


def _rand_ascii(rng: random.Random, min_len: int, max_len: int) -> str:
    n = rng.randint(min_len, max_len)
    return "".join(rng.choice(SAFE_ASCII) for _ in range(n))


def _rand_bytes(rng: random.Random, min_len: int, max_len: int) -> bytes:
    n = rng.randint(min_len, max_len)
    bs = bytearray()
    for _ in range(n):
        if rng.random() < 0.75:
            bs.append(ord(rng.choice(SAFE_ASCII)))
        else:
            bs.append(rng.randrange(0, 256))
    return bytes(bs)


def _filename(rng: random.Random) -> str:
    bases = [
        _rand_ascii(rng, 3, 12),
        _rand_ascii(rng, 1, 8) + ".txt",
        _rand_ascii(rng, 1, 8) + ".bin",
        _rand_ascii(rng, 1, 8) + ".jpg",
    ]
    base = rng.choice(bases)
    if rng.random() < 0.4:
        dirs = [
            _rand_ascii(rng, 3, 8),
            _rand_ascii(rng, 3, 8),
        ]
        sep = "/" if rng.random() < 0.7 else "\\"
        return sep.join(dirs + [base])
    return base


def _form_name(rng: random.Random) -> str:
    common = [
        "file", "upload", "avatar", "data", "meta", "description", "token", "id",
    ]
    if rng.random() < 0.6:
        return rng.choice(common)
    return _rand_ascii(rng, 3, 16).replace(" ", "_")


def _boundary(rng: random.Random) -> str:
    length = rng.randint(16, 60)
    core_chars = string.ascii_letters + string.digits + "'()+_,-./:=?"
    core = "".join(rng.choice(core_chars) for _ in range(length))
    if rng.random() < 0.9:
        core = ("-" * rng.randint(5, 12)) + core
    return core


def _enc_u16_le(n: int) -> bytes:
    return bytes((n & 0xFF, (n >> 8) & 0xFF))


def _pack_len_prefixed(b: bytes, len_bytes: int) -> bytes:
    if len_bytes == 1:
        return bytes((len(b) & 0xFF,)) + b
    elif len_bytes == 2:
        return _enc_u16_le(len(b)) + b
    else:
        raise ValueError("len_bytes must be 1 or 2")


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    num_parts = rng.randint(1, 3)
    out = bytearray()
    out.append(num_parts & 0xFF)

    for _ in range(num_parts):
        if rng.random() < 0.5:
            payload = _rand_bytes(rng, 0, 1024)
        else:
            choice = rng.random()
            if choice < 0.34:
                kv = [
                    ("key", _rand_ascii(rng, 1, 12)),
                    ("value", _rand_ascii(rng, 0, 24)),
                ]
                payload = "&".join(f"{k}={v}" for k, v in kv).encode("utf-8", errors="ignore")
            elif choice < 0.67:
                ok_str = "true" if rng.random() < 0.5 else "false"
                payload = ("{"
                           + f"\"name\":\"{_rand_ascii(rng,3,10).strip()}\"," 
                           + f"\"n\":{rng.randint(0, 1000)},"
                           + f"\"ok\":{ok_str}"
                           + "}").encode("utf-8", errors="ignore")
            else:
                payload = _rand_ascii(rng, 0, 1024).encode("utf-8", errors="ignore")

        out += _pack_len_prefixed(payload, 2)

        has_cd = 1 if rng.random() < 0.7 else 0
        out.append(has_cd)
        if has_cd:
            name = _form_name(rng).encode("utf-8", errors="ignore")
            filename = _filename(rng).encode("utf-8", errors="ignore")
            name = name[:255]
            filename = filename[:255]
            out += _pack_len_prefixed(name, 1)
            out += _pack_len_prefixed(filename, 1)

    if rng.random() < 0.85:
        bstr = _boundary(rng).encode("ascii", errors="ignore")[:255]
    else:
        bstr = b""
    out += _pack_len_prefixed(bstr, 1)

    return bytes(out[:4096])

import random
import string
from typing import List

# Data type: proxy URL string
# Goal: Generate valid, interesting proxy specification strings that cover:
# - host:port (IPv4, IPv6, hostname)
# - with/without scheme (http, https, socks5)
# - with optional credentials (user:pass@)
# - with paths or query fragments (though typically ignored, still valid strings)
# - edge numeric ports, common proxy ports, unusual but valid chars in user/pass and host labels
# - Unicode punycode-like labels and percent-encoding
# Output bytes should be <= 4096 and deterministic given a seed.

COMMON_SCHEMES = [
    "http",
    "https",
    "socks5",
    "socks4",
]

COMMON_PORTS = [80, 1080, 3128, 8000, 8001, 8080, 8081, 8888, 443, 21, 22, 25, 53]
EDGE_PORTS = [1, 9, 19, 1023, 1024, 65535]

HOST_LABEL_CHARS = string.ascii_lowercase + string.digits + "-"
USER_SAFE = string.ascii_letters + string.digits + "._-"
PASS_SAFE = USER_SAFE + "!$()*+,;=@"  # allow reserved but common in creds


def _rand_hostname(r: random.Random) -> str:
    # Generate hostname with 1-4 labels, each 1-20 chars, start/end alnum
    labels = []
    nlabels = r.randint(1, 4)
    for _ in range(nlabels):
        length = r.randint(1, 20)
        # ensure start/end alnum
        core_len = max(1, length - 2)
        core = "".join(r.choice(HOST_LABEL_CHARS) for _ in range(core_len))
        start = r.choice(string.ascii_lowercase + string.digits)
        end = r.choice(string.ascii_lowercase + string.digits)
        labels.append(start + core + end if length >= 2 else start)
    # Optionally include punycode-like label
    if r.random() < 0.2:
        labels.insert(0, "xn--" + "".join(r.choice(string.ascii_lowercase + string.digits) for _ in range(r.randint(4, 10))))
    return ".".join(labels)


def _rand_ipv4(r: random.Random) -> str:
    return ".".join(str(r.randint(0, 255)) for _ in range(4))


def _rand_ipv6(r: random.Random) -> str:
    # Produce a full or compressed IPv6
    hextets = ["%x" % r.randint(0, 0xFFFF) for _ in range(8)]
    if r.random() < 0.7:
        # compress a random run of zeros
        zstart = r.randint(0, 7)
        zend = r.randint(zstart, 7)
        if zstart < zend:
            for i in range(zstart, zend + 1):
                hextets[i] = "0"
            # build with ::
            left = ":".join(h for h in hextets[:zstart] if h is not None)
            right = ":".join(h for h in hextets[zend + 1:] if h is not None)
            if left and right:
                return left + "::" + right
            elif left:
                return left + "::"
            elif right:
                return "::" + right
            else:
                return "::"
    return ":".join(hextets)


def _maybe_userinfo(r: random.Random) -> str:
    if r.random() < 0.5:
        user_len = r.randint(1, 12)
        pass_len = r.randint(0, 16)
        user = "".join(r.choice(USER_SAFE) for _ in range(user_len))
        # occasionally percent-encode some bytes in user
        if r.random() < 0.2:
            user += "%" + ("%02X" % r.randint(0, 255))
        if pass_len:
            pwd = "".join(r.choice(PASS_SAFE) for _ in range(pass_len))
            if r.random() < 0.2:
                pwd = pwd[: max(0, len(pwd) - 1)] + "%3A"  # include encoded ':'
            return f"{user}:{pwd}@"
        else:
            return f"{user}@"
    return ""


def _maybe_path_query(r: random.Random) -> str:
    # Some proxies ignore these, but include them to exercise parsing
    s = ""
    if r.random() < 0.35:
        path_len = r.randint(1, 10)
        segs = []
        for _ in range(r.randint(1, 3)):
            seg = "".join(r.choice(string.ascii_letters + string.digits + "-._~") for _ in range(path_len))
            segs.append(seg)
        s += "/" + "/".join(segs)
    if r.random() < 0.3:
        qpairs = []
        for _ in range(r.randint(1, 3)):
            k = "".join(r.choice(string.ascii_lowercase) for _ in range(r.randint(1, 5)))
            v = "".join(r.choice(string.ascii_lowercase + string.digits) for _ in range(r.randint(0, 6)))
            qpairs.append(f"{k}={v}")
        s += "?" + "&".join(qpairs)
    if r.random() < 0.2:
        s += "#frag"
    return s


def _choose_host(r: random.Random) -> str:
    t = r.random()
    if t < 0.4:
        return _rand_hostname(r)
    elif t < 0.7:
        return _rand_ipv4(r)
    else:
        return "[" + _rand_ipv6(r) + "]"  # IPv6 literal form


def _choose_port(r: random.Random) -> int:
    roll = r.random()
    if roll < 0.6:
        return r.choice(COMMON_PORTS)
    elif roll < 0.9:
        return r.randint(1, 65535)
    else:
        return r.choice(EDGE_PORTS)


def _maybe_scheme(r: random.Random) -> str:
    if r.random() < 0.7:
        return r.choice(COMMON_SCHEMES) + "://"
    return ""


def _build_proxy_string(r: random.Random) -> str:
    parts = []
    parts.append(_maybe_scheme(r))
    parts.append(_maybe_userinfo(r))
    host = _choose_host(r)
    # Optionally embed a username in IPv6 hostinfo incorrectly to exercise robustness, but keep valid by only sometimes
    parts.append(host)
    if r.random() < 0.95:
        parts.append(":" + str(_choose_port(r)))
    if r.random() < 0.25:
        parts.append(_maybe_path_query(r))
    return "".join(parts)


def _dedupe_variants(base: str) -> List[str]:
    # Produce a small set of related variants to hit different code paths.
    variants = [base]
    # Without port
    if ":" in base:
        try:
            scheme_split = base.split("//", 1)
            after = scheme_split[1] if len(scheme_split) == 2 else scheme_split[0]
            # remove :port only at the last colon if host isn't IPv6 literal
            if not after.startswith("["):
                hostport = after.split("/", 1)[0]
                rest = after[len(hostport):]
                if hostport.count(":") == 1:
                    host_only = hostport.split(":", 1)[0]
                    v = (scheme_split[0] + "//" if len(scheme_split) == 2 else "") + host_only + rest
                    variants.append(v)
        except Exception:
            pass
    # With and without scheme
    if "//" in base:
        variants.append(base.split("//", 1)[1])
    else:
        # add http scheme
        variants.append("http://" + base)
    # Credentials variant
    if "@" not in base:
        variants.append("http://user:pass@" + base)
    return list(dict.fromkeys(variants))[:4]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    base = _build_proxy_string(r)
    # Choose one of a few coherent variants to provide diverse yet valid inputs.
    choices = _dedupe_variants(base)
    s = r.choice(choices)
    # Ensure length bound
    if len(s) > 1024:
        s = s[:1024]
    return s.encode("utf-8", errors="strict")

import os
import random
import string
from typing import List

# Generator for a valid filesystem path string to a file for WebContext::load_cacert.
# Returns bytes containing a plausible certificate bundle filename/path.

MAX_LEN = 4096

_common_dirs = [
    "certs", "ssl", "tls", "etc", "config", "conf", "security", "data", "tmp", "var", "run"
]
_common_names = [
    "ca-certificates", "cacert", "ca-bundle", "ca", "root", "trust", "bundle", "certchain"
]
_common_exts = [
    ".pem", ".crt", ".cer", ".der", ".bundle", ".p7b"
]

_unix_roots = [
    "/etc/ssl/certs",
    "/etc/pki/ca-trust/extracted/pem",
    "/usr/local/share/ca-certificates",
    "/etc/pki/tls/certs",
]
_win_roots = [
    "C:\\Windows\\System32\\certs",
    "C:\\ProgramData\\ssl",
    "C:\\certs",
    "C:\\temp",
]

_safe_chars = string.ascii_letters + string.digits + "-_ ."


def _rand_rel_component(rng: random.Random, min_len=3, max_len=12) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(_safe_chars) for _ in range(n)).strip()


def _rand_dir_path(rng: random.Random, sep: str, depth_range=(1, 4)) -> str:
    depth = rng.randint(*depth_range)
    parts: List[str] = []
    for _ in range(depth):
        if rng.random() < 0.5:
            parts.append(rng.choice(_common_dirs))
        else:
            parts.append(_rand_rel_component(rng))
    return sep.join(parts)


def _rand_filename(rng: random.Random) -> str:
    base = rng.choice(_common_names) if rng.random() < 0.7 else _rand_rel_component(rng, 3, 16)
    if rng.random() < 0.3:
        base += f"-{rng.randint(1, 5)}.{rng.randint(0, 9)}"
    ext = rng.choice(_common_exts)
    return base + ext


def _make_unix_path(rng: random.Random) -> str:
    if rng.random() < 0.5:
        root = rng.choice(_unix_roots)
        sub = _rand_dir_path(rng, '/', (0, 2))
        fname = _rand_filename(rng)
        parts = [root]
        if sub:
            parts.append(sub)
        parts.append(fname)
        return '/'.join([p for p in parts if p])
    prefix = './' if rng.random() < 0.5 else ''
    d = _rand_dir_path(rng, '/', (0, 3))
    fname = _rand_filename(rng)
    if d:
        return prefix + d + '/' + fname
    return prefix + fname


def _make_win_path(rng: random.Random) -> str:
    if rng.random() < 0.5:
        root = rng.choice(_win_roots)
        sub = _rand_dir_path(rng, '\\', (0, 2))
        fname = _rand_filename(rng)
        parts = [root]
        if sub:
            parts.append(sub)
        parts.append(fname)
        return '\\'.join([p for p in parts if p])
    d = _rand_dir_path(rng, '\\', (0, 3))
    fname = _rand_filename(rng)
    if d:
        return d + '\\' + fname
    return fname


def _maybe_mixed_separators(rng: random.Random, path: str) -> str:
    # Sometimes create mixed separators to increase coverage of path normalization
    if rng.random() < 0.2:
        path = path.replace('/', rng.choice(['/', '\\']))
    if rng.random() < 0.2:
        path = path.replace('\\', rng.choice(['/', '\\']))
    return path


def _maybe_env_like(rng: random.Random, path: str) -> str:
    # Prepend environment-variable-like components sometimes
    if rng.random() < 0.1:
        if rng.random() < 0.5:
            prefix = rng.choice(['~', '$SSL_DIR/', '$XDG_DATA_HOME/'])
            trimmed = path.lstrip('/').lstrip('\\')
            return prefix + trimmed
        else:
            trimmed = path.lstrip('/').lstrip('\\')
            return "%PROGRAMDATA%\\" + trimmed
    return path


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    flavor = rng.choice(['unix', 'win'])

    if flavor == 'unix':
        path = _make_unix_path(rng)
    else:
        path = _make_win_path(rng)

    path = _maybe_mixed_separators(rng, path)
    path = _maybe_env_like(rng, path)

    if not any(path.lower().endswith(ext) for ext in _common_exts):
        path += rng.choice(_common_exts)

    s = path.encode('utf-8', errors='ignore')[:MAX_LEN]
    if not s:
        s = b"cacert.pem"
    return s

import random
import string
from typing import List

# Generator for valid/interesting URL-encoded buffers to exercise url_decode overloads.
# Produces valid URL-encoded text with variations: unreserved, reserved, %HH, +, UTF-8 percent-encodings,
# query strings, and boundary cases. Avoids embedding literal NUL characters in the Python source.

SAFE_UNRESERVED = string.ascii_letters + string.digits + "-._~"
RESERVED = ":/?#[]@!$&'()*+,;="
HEX = "0123456789ABCDEF"

UTF8_EXAMPLES = [
    "©",  # C2 A9
    "€",  # E2 82 AC
    "✓",  # E2 9C 93
    "😀",  # F0 9F 98 80
    "雪",  # E9 9B AA
]

def pct_encode_byte(b: int) -> str:
    return "%" + HEX[(b >> 4) & 0xF] + HEX[b & 0xF]

def url_encode_component(s: str, encode_plus: bool = True) -> str:
    out = []
    for ch in s:
        if ch in SAFE_UNRESERVED:
            out.append(ch)
        elif ch == " " and encode_plus:
            out.append("+")
        else:
            for b in ch.encode("utf-8", "surrogatepass"):
                out.append(pct_encode_byte(b))
    return "".join(out)

def random_hex_triplet(rng: random.Random) -> str:
    return "%" + rng.choice(HEX) + rng.choice(HEX)

def make_valid_sequence(rng: random.Random, target_len: int) -> str:
    parts: List[str] = []
    if rng.random() < 0.3:
        parts.append("http%3A%2F%2F")  # http:// encoded
    if rng.random() < 0.3:
        parts.append("https%3A%2F%2F")

    base_segments = [
        "example.com",
        "localhost",
        "127.0.0.1",
        "[2001%3Adb8%3A%3A1]",
        url_encode_component("a b c"),
        url_encode_component("file_name.txt"),
        url_encode_component("param=value&x=1"),
    ]
    parts.append(rng.choice(base_segments))

    for _ in range(rng.randint(3, 10)):
        choice = rng.random()
        if choice < 0.2:
            run = ''.join(rng.choice(SAFE_UNRESERVED) for _ in range(rng.randint(1, 8)))
            parts.append(run)
        elif choice < 0.4:
            ch = rng.choice(RESERVED)
            if rng.random() < 0.5:
                parts.append(ch)
            else:
                parts.append(url_encode_component(ch))
        elif choice < 0.6:
            if rng.random() < 0.5:
                parts.append("+")
            else:
                parts.append("%20")
        elif choice < 0.8:
            b = rng.randrange(0, 256)
            parts.append(pct_encode_byte(b))
        else:
            s = rng.choice(UTF8_EXAMPLES)
            parts.append(url_encode_component(s))

    if rng.random() < 0.8:
        qs = []
        for _ in range(rng.randint(1, 4)):
            k = ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(1, 5)))
            v_raw = rng.choice(["x", rng.choice(UTF8_EXAMPLES), "param", "value with space"])  # simple safe set
            v = url_encode_component(v_raw)
            qs.append(f"{k}={v}")
        parts.append("?" if rng.random() < 0.7 else "%3F")
        parts.append("&".join(qs))

    s = ''.join(parts)
    if len(s) > target_len:
        cut = target_len
        if cut > 0 and s[cut-1] == '%':
            cut -= 1
        elif cut > 1 and s[cut-2] == '%':
            cut -= 2
        s = s[:max(0, cut)]
    return s

def add_edge_cases(rng: random.Random, s: str) -> str:
    extras = []
    candidates = [
        "", "+", "%20", "%2F", "%3F", "%25", "%%", "-._~", ":@/", "%00", "%7E", "%7e",
    ]
    if rng.random() < 0.7:
        extras.append(rng.choice(candidates))
    if rng.random() < 0.7:
        extras.append(rng.choice(candidates))
    if rng.random() < 0.6:
        extras.append("+" * rng.randint(1, 8))
    if rng.random() < 0.6:
        extras.append('%' + rng.choice(HEX) + rng.choice(HEX))
    if rng.random() < 0.3:
        extras.append(''.join(random_hex_triplet(rng) for _ in range(rng.randint(2, 6))))

    placement = rng.randint(0, 2)
    if placement == 0:
        return ''.join(extras) + s
    elif placement == 1:
        return s + ''.join(extras)
    else:
        mid = rng.randrange(0, len(s) + 1)
        return s[:mid] + ''.join(extras) + s[mid:]

def ensure_cstring_friendly(rng: random.Random, data: bytes) -> bytes:
    # Occasionally inject a NUL byte to test C-string early termination behavior.
    if b"\x00" in data:
        return data
    if rng.random() < 0.15:
        i = rng.randrange(0, len(data) + 1)
        return data[:i] + b"\x00" + data[i:]
    return data

def safe_randint(rng: random.Random, a: int, b: int) -> int:
    # Inclusive randint that guards against inverted ranges
    if a > b:
        a, b = b, a
    return rng.randint(a, b)

def build_buffer(rng: random.Random, max_size: int = 1024) -> str:
    choices = [0, 1, 2, 3, 4, 8, 16, 32, 64, 128, 256, max_size]
    base = rng.choice(choices)
    if base > 0:
        lo = max(0, base - 8)
        hi = min(max_size, base + 8)
        if lo > hi:
            lo, hi = hi, lo
        target_len = safe_randint(rng, lo, hi)
    else:
        target_len = safe_randint(rng, 0, min(32, max_size))
    s = make_valid_sequence(rng, target_len)
    s = add_edge_cases(rng, s)
    if len(s) > max_size:
        s = s[:max_size]
        if len(s) >= 2 and s[-2] == '%':
            s = s[:-2]
        elif len(s) >= 1 and s[-1] == '%':
            s = s[:-1]
    return s

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    segments = []
    total_budget = 1024
    max_segments = rng.randint(1, 4)
    while total_budget > 0 and len(segments) < max_segments:
        upper = min(256, total_budget)
        lower = 1 if total_budget > 0 else 0
        if upper < lower:
            break
        max_piece = safe_randint(rng, lower, upper)
        seg = build_buffer(rng, max_piece)
        segments.append(seg)
        total_budget -= len(seg)
        if rng.random() < 0.3:
            break
    s = ''.join(segments)

    if rng.random() < 0.25 and len(s) < 900:
        dense_len = safe_randint(rng, 16, 64)
        dense = ''.join(pct_encode_byte(i % 256) for i in range(dense_len))
        pos = rng.randrange(0, len(s) + 1)
        s = s[:pos] + dense + s[pos:]
        if len(s) > 1024:
            s = s[:1024]

    data = s.encode('utf-8', 'surrogatepass')
    data = ensure_cstring_friendly(rng, data)
    return data[:4096]

import random
import string
from typing import List

# Generator for valid URL-encoded strings covering diverse cases the url_decode overloads may encounter.
# Focus: produce bytes that are meaningful URL-encoded data and safe as C-strings (no embedded NULs),
# with varied composition: reserved characters, percent-escapes (upper/lower hex), UTF-8 sequences,
# spaces encoded as "+" and "%20", edge cases like consecutive percents, boundary hex, and mixed cases.

_HEX_UP = "0123456789ABCDEF"
_HEX_LO = "0123456789abcdef"
_UNRESERVED = string.ascii_letters + string.digits + "-._~"
# Characters that are often percent-encoded in URLs
_RESERVED = ":/?#[]@!$&'()*+,;="
# Additional punctuation to increase variety
_EXTRA = "{}|\\^`<>\"\t\r\n"  # note: CR/LF/TAB will get percent-encoded


def _pct_encode_byte(b: int, upper: bool) -> str:
    hx = _HEX_UP if upper else _HEX_LO
    return "%" + hx[(b >> 4) & 0xF] + hx[b & 0xF]


def _encode_utf8_codepoint(cp: int) -> bytes:
    return chr(cp).encode("utf-8", errors="strict")


def _rand_utf8_bytes(rng: random.Random) -> bytes:
    # Choose from common ranges, including multi-byte sequences
    choices = [
        (0x20, 0x7E),           # printable ASCII (avoid NUL)
        (0x00A0, 0x00FF),       # Latin-1 supplement
        (0x0100, 0x017F),       # Latin Extended-A
        (0x0400, 0x04FF),       # Cyrillic
        (0x0370, 0x03FF),       # Greek
        (0x1F300, 0x1F64F),     # Emojis and pictographs subset
    ]
    lo, hi = rng.choice(choices)
    cp = rng.randint(lo, hi)
    return _encode_utf8_codepoint(cp)


def _make_token(rng: random.Random) -> str:
    kind = rng.choices(
        population=[
            "unreserved",
            "reserved",
            "space_plus",
            "space_pct",
            "pct_ascii_upper",
            "pct_ascii_lower",
            "pct_utf8_upper",
            "pct_utf8_lower",
            "mix",
        ],
        weights=[25, 10, 10, 10, 10, 10, 8, 8, 9],
        k=1,
    )[0]

    if kind == "unreserved":
        n = rng.randint(1, 12)
        return "".join(rng.choice(_UNRESERVED) for _ in range(n))

    if kind == "reserved":
        n = rng.randint(1, 8)
        s = []
        for _ in range(n):
            ch = rng.choice(_RESERVED)
            # Occasionally percent-encode a reserved char
            if rng.random() < 0.4:
                upper = rng.random() < 0.5
                s.append(_pct_encode_byte(ord(ch), upper))
            else:
                s.append(ch)
        return "".join(s)

    if kind == "space_plus":
        # Plus-separated words
        words = ["".join(rng.choice(string.ascii_letters) for _ in range(rng.randint(1, 8))) for _ in range(rng.randint(1, 4))]
        return "+".join(words)

    if kind == "space_pct":
        words = ["".join(rng.choice(string.ascii_letters) for _ in range(rng.randint(1, 8))) for _ in range(rng.randint(1, 4))]
        return "%20".join(words)

    if kind in ("pct_ascii_upper", "pct_ascii_lower"):
        upper = kind.endswith("upper")
        n = rng.randint(1, 12)
        out = []
        for _ in range(n):
            # Choose printable ASCII excluding '%'
            ch = rng.choice(string.ascii_letters + string.digits + string.punctuation.replace('%', '') + " ")
            if ch == " ":
                # sometimes use + or %20
                out.append("+" if rng.random() < 0.5 else ("%20" if upper else "%20"))
            else:
                out.append(_pct_encode_byte(ord(ch), upper))
        return "".join(out)

    if kind in ("pct_utf8_upper", "pct_utf8_lower"):
        upper = kind.endswith("upper")
        parts: List[str] = []
        for _ in range(rng.randint(1, 4)):
            bts = _rand_utf8_bytes(rng)
            for b in bts:
                parts.append(_pct_encode_byte(b, upper))
        return "".join(parts)

    if kind == "mix":
        # A mixture of raw and percent-encoded elements including extras
        segs: List[str] = []
        for _ in range(rng.randint(2, 6)):
            choice = rng.random()
            if choice < 0.3:
                segs.append("".join(rng.choice(_UNRESERVED) for _ in range(rng.randint(1, 6))))
            elif choice < 0.55:
                # encode some EXTRA characters safely
                ch = rng.choice(_EXTRA)
                bts = ch.encode("utf-8")
                for b in bts:
                    segs.append(_pct_encode_byte(b, rng.random() < 0.5))
            elif choice < 0.8:
                # reserved possibly encoded
                ch = rng.choice(_RESERVED)
                if rng.random() < 0.5:
                    segs.append(ch)
                else:
                    segs.append(_pct_encode_byte(ord(ch), rng.random() < 0.5))
            else:
                # a small utf8 run percent-encoded
                bts = _rand_utf8_bytes(rng)
                segs.extend(_pct_encode_byte(b, rng.random() < 0.5) for b in bts)
        # sprinkle pluses and %20
        glue = rng.choice(["", "+", "%20"])
        return glue.join(segs)

    return ""


def _build_query_pair(rng: random.Random) -> str:
    key = _make_token(rng)
    val = _make_token(rng)
    # Occasionally add empty key or value
    if rng.random() < 0.1:
        key = ""
    if rng.random() < 0.1:
        val = ""
    return f"{key}={val}"


def _assemble_encoded(rng: random.Random, max_len: int) -> str:
    # Build either a single token or a query-like string with & separators
    if rng.random() < 0.6:
        segments = [_build_query_pair(rng) for _ in range(rng.randint(1, 5))]
        s = "&".join(segments)
    else:
        parts = [_make_token(rng) for _ in range(rng.randint(1, 6))]
        s = rng.choice(["", "/", "-", "_"]).join(parts)
    # Limit size to max_len
    if len(s) > max_len:
        s = s[:max_len]
    return s


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Create a primary buffer used by the fuzzer for range/len overloads
    main = _assemble_encoded(rng, 1024)

    # Create a c-string safe buffer (no embedded NULs) but url-encoded already is safe; ensure length
    cstr = _assemble_encoded(rng, 1024)

    # Create another src buffer for std::string overload
    src = _assemble_encoded(rng, 1024)

    # The target harness pulls three FUZZ_PARAM_STR values, each up to 1024 bytes.
    # Concatenate them with a simple separator header to help the harness split deterministically if it does
    # or consume sequentially if used as a single blob. Many libFuzzer-style harnesses read bytes sequentially.
    # Layout:
    # [len1:2][data1][len2:2][data2][len3:2][data3]
    # Use 16-bit big-endian lengths to stay simple and under 4096 bytes.

    def pack(s: str) -> bytes:
        b = s.encode('utf-8', errors='strict')
        if len(b) > 1024:
            b = b[:1024]
        l = len(b)
        return bytes([ (l >> 8) & 0xFF, l & 0xFF ]) + b

    payload = pack(main) + pack(cstr) + pack(src)

    # Ensure final size constraint
    if len(payload) > 4096:
        payload = payload[:4096]

    return payload
